package dashboard

import "context"

type Dashboard struct {
  Profile Profile
  Orders  []Order
  Notices []Notice
}

func Load(ctx context.Context, c *Client, userID string) (*Dashboard, error) {
  var d Dashboard
  if err := c.get(ctx, "/users/"+userID, &d.Profile); err != nil {
    return nil, err
  }
  if err := c.get(ctx, "/users/"+userID+"/orders", &d.Orders); err != nil {
    return nil, err
  }
  if err := c.get(ctx, "/users/"+userID+"/notices", &d.Notices); err != nil {
    return nil, err
  }
  return &d, nil
}

package dashboard

import (
  "context"
  "encoding/json"
  "fmt"
  "net/http"
)

type Client struct {
  http *http.Client
  base string
}

func (c *Client) get(ctx context.Context, path string, out any) error {
  resp, err := c.http.Get(c.base + path)
  if err != nil {
    return err
  }
  defer resp.Body.Close()
  if resp.StatusCode != http.StatusOK {
    return fmt.Errorf("GET %s: %s", path, resp.Status)
  }
  return json.NewDecoder(resp.Body).Decode(out)
}

