func (c *Client) get(ctx context.Context, path string, out any) error {
  req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.base+path, nil)
  if err != nil {
    return err
  }
  resp, err := c.http.Do(req)
  if err != nil {
    return err
  }
  defer resp.Body.Close()
  if resp.StatusCode != http.StatusOK {
    return fmt.Errorf("GET %s: %s", path, resp.Status)
  }
  return json.NewDecoder(resp.Body).Decode(out)
}

type Dashboard struct {
  Profile Profile
  Orders  []Order
  Notices []Notice
  Avatars []Avatar
}

func Load(ctx context.Context, c *Client, userID string, friendIDs []string) (*Dashboard, error) {
  d := Dashboard{Avatars: make([]Avatar, len(friendIDs))}
  g, ctx := errgroup.WithContext(ctx)
  g.SetLimit(8)
  g.Go(func() error {
    return c.get(ctx, "/users/"+userID, &d.Profile)
  })
  g.Go(func() error {
    return c.get(ctx, "/users/"+userID+"/orders", &d.Orders)
  })
  g.Go(func() error {
    return c.get(ctx, "/users/"+userID+"/notices", &d.Notices)
  })
  for i, id := range friendIDs {
    g.Go(func() error {
      return c.get(ctx, "/users/"+id+"/avatar", &d.Avatars[i])
    })
  }
  if err := g.Wait(); err != nil {
    return nil, err
  }
  return &d, nil
}
